import hashlib
import os
import json
import re
from functools import lru_cache
from typing import Dict, Optional, Tuple

# Feature flags loaded from environment
FEATURE_FLAGS = {
    "enable_pragma_normalization": os.environ.get("FF_PRAGMA_NORM", "true") == "true",
    "enable_import_resolution": os.environ.get("FF_IMPORT_RES", "true") == "true",
    "cache_compiled_artifacts": os.environ.get("FF_CACHE_ARTIFACTS", "true") == "true",
    "strict_version_pinning": os.environ.get("FF_STRICT_PIN", "true") == "true",
}

class SoliditySourceNormalizer:
    """Normalizes Solidity source before compilation to improve cache hit rates."""

    PRAGMA_PATTERN = re.compile(r'pragma\s+solidity\s+([^;]+);')
    IMPORT_PATTERN = re.compile(r'import\s+["\']([^"\']+)["\'];')
    COMMENT_PATTERN = re.compile(r'//[^\n]*|/\*[\s\S]*?\*/')

    def __init__(self, feature_flags: Dict[str, bool]):
        self.flags = feature_flags

    def normalize(self, source: str) -> str:
        """Normalize source for consistent cache key generation."""
        normalized = source

        # Strip comments for normalization purposes
        normalized = self.COMMENT_PATTERN.sub('', normalized)

        if self.flags.get("enable_pragma_normalization"):
            normalized = self._normalize_pragma(normalized)

        # Collapse whitespace
        normalized = re.sub(r'\s+', ' ', normalized).strip()

        return normalized

    def _normalize_pragma(self, source: str) -> str:
        """Normalize pragma to canonical form."""
        def replace_pragma(match):
            version_spec = match.group(1).strip()
            # Normalize version ranges to their lower bound
            version_spec = re.sub(r'\^(\d+\.\d+\.\d+)', r'>=\1', version_spec)
            return f'pragma solidity {version_spec};'
        return self.PRAGMA_PATTERN.sub(replace_pragma, source)


class CompilationCache:
    """Cache for compiled Solidity artifacts keyed by normalized source hash."""

    def __init__(self, feature_flags: Dict[str, bool]):
        self.flags = feature_flags
        self.normalizer = SoliditySourceNormalizer(feature_flags)
        self._cache: Dict[str, dict] = {}
        self._key_metadata: Dict[str, dict] = {}

    def _compute_cache_key(self, source: str, compiler_version: str, 
                           optimization_runs: int) -> str:
        """Compute cache key from normalized source and compiler settings."""
        normalized = self.normalizer.normalize(source)

        # Build key components
        key_parts = [normalized]

        if self.flags.get("strict_version_pinning"):
            key_parts.append(compiler_version)
        else:
            # Use major.minor only for broader cache hits
            major_minor = '.'.join(compiler_version.split('.')[:2])
            key_parts.append(major_minor)

        key_parts.append(str(optimization_runs))

        key_material = '|'.join(key_parts)
        return hashlib.sha256(key_material.encode('utf-8')).hexdigest()

    def get(self, source: str, compiler_version: str,
            optimization_runs: int = 200) -> Optional[dict]:
        """Retrieve cached compilation artifact."""
        if not self.flags.get("cache_compiled_artifacts"):
            return None

        cache_key = self._compute_cache_key(source, compiler_version, optimization_runs)
        return self._cache.get(cache_key)

    def put(self, source: str, compiler_version: str,
            optimization_runs: int, artifact: dict) -> str:
        """Store compilation artifact in cache."""
        if not self.flags.get("cache_compiled_artifacts"):
            return ""

        cache_key = self._compute_cache_key(source, compiler_version, optimization_runs)
        self._cache[cache_key] = artifact
        self._key_metadata[cache_key] = {
            "compiler_version": compiler_version,
            "optimization_runs": optimization_runs,
            "source_length": len(source)
        }
        return cache_key


class SolidityProcessingService:
    """Main service for processing Solidity files with compilation caching."""

    def __init__(self):
        self.cache = CompilationCache(FEATURE_FLAGS)
        self._import_registry: Dict[str, str] = {}

    def register_import(self, path: str, source: str) -> None:
        """Register a resolved import for dependency tracking."""
        self._import_registry[path] = source

    def _resolve_imports(self, source: str) -> str:
        """Inline resolved imports into source for complete compilation unit."""
        if not FEATURE_FLAGS.get("enable_import_resolution"):
            return source

        def replace_import(match):
            import_path = match.group(1)
            if import_path in self._import_registry:
                return self._import_registry[import_path]
            return match.group(0)

        return SoliditySourceNormalizer.IMPORT_PATTERN.sub(replace_import, source)

    def process(self, source: str, compiler_version: str,
                optimization_runs: int = 200) -> Tuple[dict, bool]:
        """Process a Solidity source file. Returns (artifact, cache_hit)."""

        # Resolve imports to create full compilation unit
        full_source = self._resolve_imports(source)

        # Check cache
        cached = self.cache.get(full_source, compiler_version, optimization_runs)
        if cached is not None:
            return cached, True

        # Simulate compilation
        artifact = self._compile(full_source, compiler_version, optimization_runs)

        # Store in cache
        self.cache.put(full_source, compiler_version, optimization_runs, artifact)

        return artifact, False

    def _compile(self, source: str, compiler_version: str,
                 optimization_runs: int) -> dict:
        """Simulate Solidity compilation."""
        return {
            "bytecode": hashlib.sha256(source.encode()).hexdigest()[:40],
            "abi": [],
            "compiler": compiler_version,
            "optimized": optimization_runs > 0
        }


def create_service() -> SolidityProcessingService:
    """Factory function for the processing service."""
    return SolidityProcessingService()
